const menuButton = document.querySelector('.menu-toggle');
const mobileMenu = document.getElementById('mobile-menu');

function closeMenu(returnFocus = false) {
  menuButton.setAttribute('aria-expanded', 'false');
  menuButton.setAttribute('aria-label', language === 'ja' ? 'メニューを開く' : 'Open menu');
  mobileMenu.hidden = true;
  if (returnFocus) menuButton.focus();
}
function setLanguage(nextLanguage) {
  language = nextLanguage === 'ja' ? 'ja' : 'en';
  document.documentElement.lang = language;
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    el.innerHTML = language === 'ja' ? translations[key] || english.get(key) : english.get(key);
  });
  document.querySelectorAll('[data-lang]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.lang === language)));
  translatedImages.forEach(el => { el.alt = language === 'ja' ? translations[el.dataset.alt] : englishAlt.get(el); });
  document.title = language === 'ja' ? 'J Coaching — あなたの言葉で。あなたの未来へ。' : 'J Coaching — Your voice. Your future.';
  document.querySelector('meta[name="description"]').content = language === 'ja'
    ? '日本で働くあなたのための日本語コーチング。毎日のアドバイス、週1回のミーティング、仕事と目標に合う勉強の計画。'
    : 'Personal Japanese coaching for international professionals in Japan. Daily feedback, weekly one-to-one sessions, and a plan built around your career.';
  document.querySelector('.journey-tabs').setAttribute('aria-label', language === 'ja' ? '3ヶ月の勉強プラン' : 'Three-month learning journey');
  document.querySelectorAll('[data-video]').forEach(button => {
    button.setAttribute('aria-label', (language === 'ja' ? '再生：' : 'Play: ') + (language === 'ja' ? button.dataset.titleJa : button.dataset.titleEn));
  });
  document.querySelectorAll('.video-stage iframe').forEach(frame => {
    frame.title = language === 'ja' ? frame.dataset.titleJa : frame.dataset.titleEn;
  });
  closeMenu();
  try { localStorage.setItem('jcoaching-language', language); } catch (_) { /* Language switching does not depend on storage. */ }
}
document.querySelectorAll('[data-lang]').forEach(button => button.addEventListener('click', () => setLanguage(button.dataset.lang)));
let savedLanguage = 'en';
try { savedLanguage = localStorage.getItem('jcoaching-language') || 'en'; } catch (_) { /* Use English. */ }
setLanguage(savedLanguage);

menuButton.addEventListener('click', () => {
  const expanded = menuButton.getAttribute('aria-expanded') === 'true';
  menuButton.setAttribute('aria-expanded', String(!expanded));
  menuButton.setAttribute('aria-label', language === 'ja' ? (expanded ? 'メニューを開く' : 'メニューを閉じる') : (expanded ? 'Open menu' : 'Close menu'));
  mobileMenu.hidden = expanded;
});
mobileMenu.querySelectorAll('a').forEach(link => link.addEventListener('click', () => closeMenu()));
document.addEventListener('keydown', event => {
  if (event.key === 'Escape' && !mobileMenu.hidden) closeMenu(true);
});
const desktopViewport = window.matchMedia('(min-width: 961px)');
if (desktopViewport.addEventListener) desktopViewport.addEventListener('change', event => { if (event.matches) closeMenu(); });

const tabs = [...document.querySelectorAll('[data-month]')];
function selectMonth(tab, focus = false) {
  tabs.forEach(button => {
    const selected = button === tab;
    button.setAttribute('aria-selected', String(selected));
    button.tabIndex = selected ? 0 : -1;
    document.getElementById(button.getAttribute('aria-controls')).hidden = !selected;
  });
  if (focus) tab.focus();
}
tabs.forEach((tab, index) => {
  tab.addEventListener('click', () => selectMonth(tab));
  tab.addEventListener('keydown', event => {
    let next;
    if (event.key === 'ArrowRight') next = (index + 1) % tabs.length;
    if (event.key === 'ArrowLeft') next = (index + tabs.length - 1) % tabs.length;
    if (event.key === 'Home') next = 0;
    if (event.key === 'End') next = tabs.length - 1;
    if (next !== undefined) { event.preventDefault(); selectMonth(tabs[next], true); }
  });
});

// A direct YouTube link is available beside every video, including without JavaScript.
document.querySelectorAll('[data-video]').forEach(button => {
  button.addEventListener('click', () => {
    const id = button.dataset.video;
    if (!['x6UmHrxnJnk', 'a3Rw8I9yS4Q'].includes(id)) return;
    const frame = document.createElement('iframe');
    frame.src = 'https://www.youtube-nocookie.com/embed/' + id + '?autoplay=1&rel=0';
    frame.dataset.titleEn = button.dataset.titleEn;
    frame.dataset.titleJa = button.dataset.titleJa;
    frame.title = language === 'ja' ? frame.dataset.titleJa : frame.dataset.titleEn;
    frame.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen';
    frame.allowFullscreen = true;
    frame.referrerPolicy = 'strict-origin-when-cross-origin';
    frame.tabIndex = 0;
    button.replaceWith(frame);
    frame.focus();
  });
});

if ('IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.remove('will-reveal');
        entry.target.classList.add('revealed');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08 });
  document.querySelectorAll('.reveal').forEach(el => {
    if (el.getBoundingClientRect().top > window.innerHeight) {
      el.classList.add('will-reveal');
      observer.observe(el);
    }
  });
}
